mapper.select:
SELECT mr.*, ss.name AS supplier_name, su.phone, IFNULL(t1.deducted_behavior_score, 0) AS deducted_behavior_score, mr.behavior_total_score - IFNULL(t1.deducted_behavior_score, 0) AS remaining_behavior_score, IFNULL(t1.penalty, 0) as cumulative_penalty, su.username FROM project_manage_roster mr LEFT JOIN scm_supplier ss ON ss.bool_delete_enum = 0 AND ss.id = mr.supplier_id LEFT JOIN sys_user su ON su.bool_delete_enum = 0 AND su.id = mr.user_id LEFT JOIN ( SELECT mbq.user_id,mbq.project_id, SUM( CASE WHEN mbq.type = 1 THEN mqcc.behavior_score WHEN mbq.type IN (2, 4) THEN mscc.behavior_score ELSE 0 END ) AS deducted_behavior_score, SUM( CASE WHEN mbq.type = 1 THEN mqcc.penalty WHEN mbq.type IN (2, 4) THEN mscc.penalty ELSE 0 END ) AS penalty FROM project_qhse_problem mbq LEFT JOIN mes_quality_class_config mqcc ON mqcc.bool_delete_enum = 0 AND mqcc.id = mbq.problem_id AND mbq.type = 1 LEFT JOIN mes_safety_class_config mscc ON mscc.bool_delete_enum = 0 AND mscc.id = mbq.problem_id AND mbq.type IN (2, 4) WHERE mbq.bool_delete_enum = 0 AND YEAR(mbq.create_time) = YEAR(NOW()) and mbq.is_internal = 0 GROUP BY mbq.user_id,mbq.project_id )as t1 on t1.user_id = mr.user_id and t1.project_id = mr.project_id WHERE mr.bool_delete_enum = 0
AND mr.project_id = #{projectId}
AND mr.id = #{id}
AND mr.status = #{status}
AND mr.nation = #{nation}
AND mr.sex = #{sex}
AND mr.name LIKE #{nameLike}
AND mr.id_number LIKE #{idNumberLike}
AND su.phone LIKE #{phoneLike}
AND mr.supplier_id = #{supplierId}
AND mr.user_id = #{userId}
